// ────────────────────────────────────────────────────────────────────────────
//  STORAGE HELPERS  — uses window.storage (shared) so admin sees all
// ────────────────────────────────────────────────────────────────────────────
const KEY_PREFIX = "ropsx2026:reg:";

const saveRegistration = async (reg) => {
  const key = KEY_PREFIX + reg.id;
  await window.storage.set(key, JSON.stringify(reg), true);
};

const loadAllRegistrations = async () => {
  try {
    const list = await window.storage.list(KEY_PREFIX, true);
    if (!list || !list.keys || list.keys.length === 0) return [];
    const results = await Promise.all(
      list.keys.map(async (k) => {
        try {
          const r = await window.storage.get(k, true);
          return r ? JSON.parse(r.value) : null;
        } catch {
          return null;
        }
      })
    );
    return results.filter(Boolean).sort((a, b) =>
      (b.createdAt || "").localeCompare(a.createdAt || "")
    );
  } catch {
    return [];
  }
};

const updateRegistration = async (id, patch) => {
  const key = KEY_PREFIX + id;
  const existing = await window.storage.get(key, true);
  if (!existing) return null;
  const merged = { ...JSON.parse(existing.value), ...patch };
  await window.storage.set(key, JSON.stringify(merged), true);
  return merged;
};

const deleteRegistration = async (id) => {
  await window.storage.delete(KEY_PREFIX + id, true);
};

