function Field({ label, required, children, help, error }) {
  return (
    <label className="block">
      <div className="flex items-baseline justify-between mb-1.5">
        <span className="font-body text-micro uppercase tracking-w2 text-ink-2">
          {label}
          {required && <span className="text-ember ml-0.5">*</span>}
        </span>
        {help && (
          <span className="font-body text-mini text-taupe italic">{help}</span>
        )}
      </div>
      {children}
      {error && (
        <div className="flex items-center gap-1 mt-1 font-body text-micro text-ember">
          <AlertCircle size={12} />
          <span>{error}</span>
        </div>
      )}
    </label>
  );
}

const inputBase =
  "w-full bg-transparent border-b hairline border-b-15 py-2.5 px-0 font-body text-15 text-ink placeholder-taupe-60 focus-ring transition-colors";

function TextInput(props) {
  return <input {...props} className={inputBase + " " + (props.className || "")} />;
}

function TextArea(props) {
  return (
    <textarea
      {...props}
      rows={props.rows || 3}
      className={
        "w-full bg-transparent border hairline rounded-sm py-3 px-3 font-body text-15 text-ink placeholder-taupe-60 focus-ring transition-colors resize-none " +
        (props.className || "")
      }
    />
  );
}

function Select({ value, onChange, options, ...rest }) {
  return (
    <select
      value={value}
      onChange={onChange}
      {...rest}
      className={inputBase + " appearance-none bg-cream cursor-pointer"}
    >
      <option value="">— Select —</option>
      {options.map((o) => (
        <option key={o} value={o}>
          {o}
        </option>
      ))}
    </select>
  );
}

