// ────────────────────────────────────────────────────────────────────────────
//  REGISTRATION FORM
// ────────────────────────────────────────────────────────────────────────────
const initialForm = {
  // camper
  camperName: "",
  camperDob: "",
  camperGender: "",
  tshirtSize: "",
  // parent
  parentName: "",
  parentRelationship: "",
  parentPhone: "",
  parentAltPhone: "",
  parentEmail: "",
  address: "",
  // emergency
  emergencyName: "",
  emergencyRelationship: "",
  emergencyPhone: "",
  // health
  allergies: "",
  medicalConditions: "",
  medications: "",
  // logistics
  dropoffLocation: "",
  // notes
  notes: "",
  // consent
  consent: false,
};

function RegistrationForm({ onSubmitted, formRef }) {
  const [form, setForm] = useState(initialForm);
  const [errors, setErrors] = useState({});
  const [submitting, setSubmitting] = useState(false);
  const [submitted, setSubmitted] = useState(null); // submitted registration

  const set = (k) => (e) => {
    const v = e?.target?.type === "checkbox" ? e.target.checked : e.target.value;
    setForm((f) => ({ ...f, [k]: v }));
    if (errors[k]) setErrors((er) => ({ ...er, [k]: undefined }));
  };

  const validate = () => {
    const err = {};
    if (!form.camperName.trim()) err.camperName = "Camper name is required";
    if (!form.camperDob) err.camperDob = "Date of birth is required";
    if (!form.camperGender) err.camperGender = "Please select";
    if (!form.parentName.trim()) err.parentName = "Parent/guardian name required";
    if (!form.parentPhone.trim()) err.parentPhone = "Primary phone required";
    if (form.parentEmail && !/^\S+@\S+\.\S+$/.test(form.parentEmail))
      err.parentEmail = "Enter a valid email";
    if (!form.emergencyName.trim()) err.emergencyName = "Emergency contact required";
    if (!form.emergencyPhone.trim()) err.emergencyPhone = "Emergency phone required";
    if (!form.dropoffLocation) err.dropoffLocation = "Choose a drop-off location";
    if (!form.consent) err.consent = "Parent/guardian consent is required";
    return err;
  };

  const handleSubmit = async () => {
    const err = validate();
    setErrors(err);
    if (Object.keys(err).length > 0) {
      // scroll to first error
      const firstKey = Object.keys(err)[0];
      const el = document.querySelector(`[data-field="${firstKey}"]`);
      if (el) el.scrollIntoView({ behavior: "smooth", block: "center" });
      return;
    }

    setSubmitting(true);
    try {
      const id =
        "reg_" +
        Date.now().toString(36) +
        "_" +
        Math.random().toString(36).slice(2, 7);
      const reg = {
        id,
        createdAt: new Date().toISOString(),
        ...form,
        paymentStatus: "unpaid",
        amountPaid: null,
        paidAt: null,
        paymentReference: "",
      };
      await saveRegistration(reg);
      setSubmitted(reg);
      onSubmitted && onSubmitted(reg);
    } catch (e) {
      alert("Could not save registration. Please try again.");
    } finally {
      setSubmitting(false);
    }
  };

  if (submitted) {
    return <Confirmation reg={submitted} onAnother={() => { setSubmitted(null); setForm(initialForm); }} />;
  }

  return (
    <section
      ref={formRef}
      className="bg-cream py-20 px-6 md:px-10"
    >
      <div className="max-w-3xl mx-auto">
        <div className="mb-12 text-center">
          <div className="font-body text-micro uppercase tracking-w4 text-ember mb-3">
            Camper Registration
          </div>
          <h2 className="font-display text-ink text-4xl md:text-5xl tracking-tight">
            Reserve a place
            <span className="ital"> by the fire.</span>
          </h2>
          <p className="font-body text-ink-2 mt-4 max-w-xl mx-auto">
            Fill in the details below. After submission you'll receive payment instructions —
            send proof of payment and we'll mark your slot as confirmed.
          </p>
        </div>

        {/* SECTION 1 — CAMPER */}
        <div className="mb-12">
          <SectionHeader number="01" title="The Camper" sub="Tell us about the young person attending." />
          <div className="grid md:grid-cols-2 gap-x-8 gap-y-6">
            <div data-field="camperName" className="md:col-span-2">
              <Field label="Full Name" required error={errors.camperName}>
                <TextInput
                  value={form.camperName}
                  onChange={set("camperName")}
                  placeholder="e.g. Tamara Banda"
                />
              </Field>
            </div>
            <div data-field="camperDob">
              <Field label="Date of Birth" required error={errors.camperDob}>
                <TextInput
                  type="date"
                  value={form.camperDob}
                  onChange={set("camperDob")}
                />
              </Field>
            </div>
            <div data-field="camperGender">
              <Field label="Gender" required error={errors.camperGender}>
                <Select
                  value={form.camperGender}
                  onChange={set("camperGender")}
                  options={["Male", "Female"]}
                />
              </Field>
            </div>
            <Field label="T-Shirt Size" help="for the camp pack">
              <Select
                value={form.tshirtSize}
                onChange={set("tshirtSize")}
                options={["XS", "S", "M", "L", "XL", "XXL"]}
              />
            </Field>
          </div>
        </div>

        {/* SECTION 2 — PARENT */}
        <div className="mb-12">
          <SectionHeader number="02" title="Parent / Guardian" sub="Who is registering this camper?" />
          <div className="grid md:grid-cols-2 gap-x-8 gap-y-6">
            <div data-field="parentName">
              <Field label="Full Name" required error={errors.parentName}>
                <TextInput value={form.parentName} onChange={set("parentName")} />
              </Field>
            </div>
            <Field label="Relationship to Camper">
              <Select
                value={form.parentRelationship}
                onChange={set("parentRelationship")}
                options={["Mother", "Father", "Guardian", "Aunt", "Uncle", "Grandparent", "Other"]}
              />
            </Field>
            <div data-field="parentPhone">
              <Field label="Primary Phone" required error={errors.parentPhone}>
                <TextInput
                  type="tel"
                  value={form.parentPhone}
                  onChange={set("parentPhone")}
                  placeholder="+260 9..."
                />
              </Field>
            </div>
            <Field label="Alternative Phone">
              <TextInput
                type="tel"
                value={form.parentAltPhone}
                onChange={set("parentAltPhone")}
              />
            </Field>
            <div data-field="parentEmail" className="md:col-span-2">
              <Field label="Email" error={errors.parentEmail}>
                <TextInput
                  type="email"
                  value={form.parentEmail}
                  onChange={set("parentEmail")}
                  placeholder="parent@example.com"
                />
              </Field>
            </div>
            <div className="md:col-span-2">
              <Field label="Home Address">
                <TextInput
                  value={form.address}
                  onChange={set("address")}
                  placeholder="House/Plot No., Area, City"
                />
              </Field>
            </div>
          </div>
        </div>

        {/* SECTION 3 — EMERGENCY */}
        <div className="mb-12">
          <SectionHeader
            number="03"
            title="Emergency Contact"
            sub="Someone we can reach if the parent/guardian is unavailable."
          />
          <div className="grid md:grid-cols-2 gap-x-8 gap-y-6">
            <div data-field="emergencyName">
              <Field label="Full Name" required error={errors.emergencyName}>
                <TextInput value={form.emergencyName} onChange={set("emergencyName")} />
              </Field>
            </div>
            <Field label="Relationship">
              <TextInput value={form.emergencyRelationship} onChange={set("emergencyRelationship")} />
            </Field>
            <div data-field="emergencyPhone" className="md:col-span-2">
              <Field label="Phone Number" required error={errors.emergencyPhone}>
                <TextInput
                  type="tel"
                  value={form.emergencyPhone}
                  onChange={set("emergencyPhone")}
                />
              </Field>
            </div>
          </div>
        </div>

        {/* SECTION 4 — HEALTH */}
        <div className="mb-12">
          <SectionHeader
            number="04"
            title="Health Information"
            sub="Help our team care well for the camper. Leave blank if none."
          />
          <div className="grid md:grid-cols-2 gap-x-8 gap-y-6">
            <Field label="Allergies">
              <TextArea
                value={form.allergies}
                onChange={set("allergies")}
                placeholder="Foods, medication, environmental..."
              />
            </Field>
            <Field label="Medical Conditions">
              <TextArea
                value={form.medicalConditions}
                onChange={set("medicalConditions")}
                placeholder="Asthma, diabetes, etc."
              />
            </Field>
            <div className="md:col-span-2">
              <Field label="Medications" help="dosage and timing if applicable">
                <TextArea
                  value={form.medications}
                  onChange={set("medications")}
                  placeholder="List any medications the camper takes daily..."
                />
              </Field>
            </div>
          </div>
        </div>

        {/* SECTION 5 — DROP-OFF (visual toggle) */}
        <div className="mb-12">
          <SectionHeader
            number="05"
            title="Drop-off Location"
            sub="Where would you like to drop your camper for transport to camp?"
          />
          <div data-field="dropoffLocation" className="grid md:grid-cols-2 gap-4">
            <DropoffOption
              selected={form.dropoffLocation === "church"}
              onClick={() => setForm((f) => ({ ...f, dropoffLocation: "church" }))}
              icon={<Church size={32} strokeWidth={1.4} />}
              title="At the Church"
              meta={CHURCH_ADDRESS}
              detail="The team will travel together to the campsite as a group."
            />
            <DropoffOption
              selected={form.dropoffLocation === "campsite"}
              onClick={() => setForm((f) => ({ ...f, dropoffLocation: "campsite" }))}
              icon={<Tent size={32} strokeWidth={1.4} />}
              title="At the Camp Site"
              meta={VENUE}
              detail="You will drive your camper directly to the camp venue."
            />
          </div>
          {errors.dropoffLocation && (
            <div className="mt-2 flex items-center gap-1 font-body text-small text-ember">
              <AlertCircle size={12} />
              <span>{errors.dropoffLocation}</span>
            </div>
          )}
        </div>

        {/* SECTION 6 — NOTES & CONSENT */}
        <div className="mb-12">
          <SectionHeader number="06" title="Anything Else" sub="Special requests or things we should know." />
          <Field label="Notes" help="optional">
            <TextArea
              value={form.notes}
              onChange={set("notes")}
              rows={4}
              placeholder="Dietary preferences, traveling with a sibling, etc."
            />
          </Field>

          <div data-field="consent" className="mt-8 border-t hairline pt-6">
            <label className="flex items-start gap-3 cursor-pointer group">
              <span
                className={
                  "mt-0.5 w-5 h-5 rounded-sm border-15 flex items-center justify-center shrink-0 transition-colors " +
                  (form.consent
                    ? "bg-ink border-ink"
                    : "bg-transparent border-taupe group-hover-border-ink")
                }
              >
                {form.consent && (
                  <Check size={13} className="text-cream" strokeWidth={3} />
                )}
              </span>
              <input
                type="checkbox"
                className="hidden"
                checked={form.consent}
                onChange={set("consent")}
              />
              <span className="font-body text-14 text-ink-2 leading-relaxed">
                As parent/guardian I give my consent for the camper to attend ROPs X 2026, and
                I confirm that the information provided is true and complete. I understand that
                <span className="font-medium"> registration is confirmed only upon receipt of payment</span>.
              </span>
            </label>
            {errors.consent && (
              <div className="ml-8 mt-2 flex items-center gap-1 font-body text-small text-ember">
                <AlertCircle size={12} />
                <span>{errors.consent}</span>
              </div>
            )}
          </div>
        </div>

        {/* SUBMIT */}
        <div className="flex flex-col sm:flex-row items-center justify-between gap-6 border-t hairline pt-8">
          <div className="font-body text-small text-taupe max-w-sm">
            Once submitted, you'll see payment details. Send proof to the camp coordinator —
            the system will update your camper's status to{" "}
            <span className="text-forest font-semibold">paid</span>.
          </div>
          <button
            onClick={handleSubmit}
            disabled={submitting}
            className="group inline-flex items-center gap-3 bg-ember hover-bg-ember-2 disabled:opacity-50 text-cream py-4 px-9 rounded-full font-body text-13 uppercase tracking-w2 transition-colors ember-glow shrink-0"
          >
            {submitting ? "Submitting..." : "Submit Registration"}
            {!submitting && <ArrowRight size={16} className="transition-transform group-hover:translate-x-1" />}
          </button>
        </div>
      </div>
    </section>
  );
}

